    cl_kernel kernel_gemm_noshuffle_q5_0_q8_1_dp4a_wimg = ಶೂನ್ಯಸೂಚಕ;  // q5_0 dense dp4a, qs plane via texture (opt-in)
    cl_kernel kernel_gemv_noshuffle_q5_1_f32;
    cl_kernel kernel_gemm_noshuffle_q5_1_f32;
