        cl_mem ದತ್ತಾಂಶ_device = ggml_cl_create_ತಾತ್ಕಾಲಿಕ_download_ಬಫರ್(context, queue, ggml_nbytes(tensor), tensor->name);
        GGML_ASSERT(ದತ್ತಾಂಶ_device != ಖಾಲಿ && "get_tensor: temp download buffer alloc failed");

        cl_kernel kernel = backend_ctx->kernel_restore_ಖಂಡ_q4_1;
