        CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, 2, ಗಾತ್ರ(cl_mem), &ದತ್ತಾಂಶ_device));

        size_t global_work_ಗಾತ್ರ[] = {(size_t)ggml_nelements(tensor)/ggml_blck_ಗಾತ್ರ(tensor->type), 1, 1};
        size_t local_work_ಗಾತ್ರ[] = {1, 1, 1};

        cl_event evt;
        CL_CHECK(cl_ಸರತಿಗೆ_ಸೇರಿಸು_NDRange_Kernel(queue, kernel, 3, ಖಾಲಿ,
            global_work_ಗಾತ್ರ, local_work_ಗಾತ್ರ, 0, ಖಾಲಿ, &evt));
        CL_CHECK(clWaitForEvents(1, &evt));
        CL_CHECK(cl_ಸರತಿಗೆ_ಸೇರಿಸು_Read_ಬಫರ್(
            queue, ದತ್ತಾಂಶ_device, CL_TRUE, ಸ್ಥಾನಾಂತರ,
            size, ದತ್ತಾಂಶ, 0, ಖಾಲಿ, ಖಾಲಿ));
        CL_CHECK(clReleaseMemObject(ದತ್ತಾಂಶ_device));
        ಹಿಂತಿರುಗಿ;
