                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q4_0->q));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q4_0->d));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src1_image));
