                        CL_CHECK(cl_ಗಣ_Kernel_Arg(backend_ctx->kernel_moe_reorder_b, 2, ಗಾತ್ರ(cl_mem),        &buf_src1_reordered));
                        CL_CHECK(cl_ಗಣ_Kernel_Arg(backend_ctx->kernel_moe_reorder_b, 3, ಗಾತ್ರ(cl_mem),        &(backend_ctx->prealloc_ಒಟ್ಟು_tiles.ಬಫರ್)));
