                    image_src1_reordered = clCreateImage(backend_ctx->context, CL_MEM_READ_ONLY, &image_format_buf_src1, &image_desc_buf_src1, ಖಾಲಿ, &ಸ್ಥಿತಿ_2);
                    CL_CHECK(ಸ್ಥಿತಿ_2);

