                    global_ಗಾತ್ರ[0] = static_cast<size_t>(((ne01 + 63) / 64) * 64);
                    global_ಗಾತ್ರ[1] = 4;
                    global_ಗಾತ್ರ[2] = static_cast<size_t>(ne20);
                    local_ಗಾತ್ರ[1] = 4;

                    // create a sub_buffer for src1
                    region.origin = offset1;
                    region.size = ne10 * ne11 * ne12 * ಗಾತ್ರ(ದಶಮಾಂಶ);
                    src1_sub_ಬಫರ್ = cl_Create_Sub_ಬಫರ್(extra1->ದತ್ತಾಂಶ_device, 0, CL_ಬಫರ್_CREATE_TYPE_REGION, &region, &ಸ್ಥಿತಿ_2);
                    CL_CHECK(ಸ್ಥಿತಿ_2);

                    // create image for src1
                    cl_image_format image_format_buf_src1 = {CL_RGBA, CL_FLOAT};
                    cl_image_desc image_desc_buf_src1 = {CL_MEM_OBJECT_IMAGE1_D_ಬಫರ್, static_cast<size_t>(ne10 * ne11 * ne12 / 4), 0,0,0,0,0,0,0, {src1_sub_ಬಫರ್}};
                    buf_src1_image = clCreateImage(backend_ctx->context, CL_MEM_READ_ONLY, &image_format_buf_src1, &image_desc_buf_src1, ಖಾಲಿ, &ಸ್ಥಿತಿ_2);
                    CL_CHECK(ಸ್ಥಿತಿ_2);

                    // Set kernel args
                    ಪೂರ್ಣಾಂಕ arg_idx = 0;
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q5_0->qs));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q5_0->qh));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q5_0->d));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src1_image));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src2));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extrad->ದತ್ತಾಂಶ_device));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_ulong),  &offsetd));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne00));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne01));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne11));

