                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q5_1->qh));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q5_1->d));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extra0_q5_1->m));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src1_image));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src2));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &extrad->ದತ್ತಾಂಶ_device));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_ulong),  &offsetd));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne00));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne01));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne11));

