                    cl_image_desc image_desc_buf_dst = {CL_MEM_OBJECT_IMAGE1_D_ಬಫರ್, static_cast<size_t>(ne0 * ne1 * ne2), 0,0,0,0,0,0,0, {sub_buf_dst}};
                    buf_dst_image = clCreateImage(backend_ctx->context, CL_MEM_WRITE_ONLY, &image_format_buf_dst, &image_desc_buf_dst, ಖಾಲಿ, &ಸ್ಥಿತಿ_2);
                    CL_CHECK(ಸ್ಥಿತಿ_2);

                    // Set kernel args
                    ಪೂರ್ಣಾಂಕ arg_idx = 0;
