                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src2));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_src2_emap));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &buf_dst_image));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_mem),    &(backend_ctx->prealloc_ಒಟ್ಟು_tiles.ಬಫರ್)));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne00));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ),       &ne01));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_uint),       &backend_ctx->adreno_use_moe_ragged));
                    CL_CHECK(cl_ಗಣ_Kernel_Arg(kernel, arg_idx++, ಗಾತ್ರ(cl_uint),       &backend_ctx->adreno_moe_ragged_skip_gran));

                    // set thread grid
                    global_ಗಾತ್ರ[1] = static_cast<size_t>((ne01 + 63) / 64);
                    global_ಗಾತ್ರ[2] = static_cast<size_t>(max_post_ಮಾರ್ಗನಿರ್ದೇಶಕ_tile);
                    local_ಗಾತ್ರ[1] = 1;
                    local_ಗಾತ್ರ[2] = 1;

                    // Dispatch kernel
                    backend_ctx->ಸರತಿಗೆ_ಸೇರಿಸು_ndrange_kernel(kernel, 3, global_ಗಾತ್ರ, local_ಗಾತ್ರ, dst);

                    clReleaseMemObject(sub_buf_src1_pre);
                    clReleaseMemObject(buf_src1_reordered);
                    clReleaseMemObject(image_src1_reordered);
                    clReleaseMemObject(buf_src2);
                    clReleaseMemObject(buf_src2_emap);
                    clReleaseMemObject(sub_buf_dst);
                    clReleaseMemObject(buf_dst_image);
