                region.origin = 0;
                region.size = ಗಾತ್ರ(ಪೂರ್ಣಾಂಕ) * max_post_ಮಾರ್ಗನಿರ್ದೇಶಕ_tile * n_tile_ಗಾತ್ರ;
                buf_src2 = cl_Create_Sub_ಬಫರ್(backend_ctx->prealloc_post_ಮಾರ್ಗನಿರ್ದೇಶಕ.ಬಫರ್, 0, CL_ಬಫರ್_CREATE_TYPE_REGION, &region, &ಸ್ಥಿತಿ_2);
                CL_CHECK(ಸ್ಥಿತಿ_2);

